  }
}

.example.mobile {
  overflow: visible;
}

/* Aim for "standard" portrait phone dimensions */
.example.mobile .render {
  min-height: 0 !important;
  width: 256px;
  height: 510px;
  padding: 0;
  margin: 0 auto;
  background: transparent;
}

.example.mobile iframe {
  position: absolute;
  width: 320px !important;
  height: 620px;
  overflow: hidden;
  transform: scale(0.75);
  transform-origin: 32px 120px;
